"use client";

import { useEffect, useState, useRef } from "react";

export default function ClientDashboard({ tables, initialTable }: any) {
  const [selected, setSelected] = useState(initialTable);
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  const requestRef = useRef(0);

  const config = tables[selected];

  // 🔹 Fetch data safely (no race conditions)
  async function load() {
    const requestId = ++requestRef.current;

    setLoading(true);

    const res = await fetch(`/api/table?table=${selected}`);
    const json = await res.json();

    if (requestId !== requestRef.current) return;

    setData(json);
    setLoading(false);
  }

  // 🔹 Load when table changes
  useEffect(() => {
    setData([]);
    load();
  }, [selected]);

  // 🔹 Polling (safe)
  useEffect(() => {
    const interval = setInterval(() => {
      load();
    }, 3000);

    return () => clearInterval(interval);
  }, [selected]);

return (
  <div className="flex h-screen bg-gray-100">

    {/* ================= LEFT: CONTROLS ================= */}
    <aside className="w-80 bg-white p-4 border-r space-y-6">
      
      <h2 className="text-lg font-semibold">Controls</h2>

      {/* Add Form */}
      <div>
        <h3 className="text-sm font-medium mb-2">Add Element</h3>

        <form
          onSubmit={async (e) => {
            e.preventDefault();
            const fd = new FormData(e.currentTarget);

            await fetch("/api/insert", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                table: selected,
                data: Object.fromEntries(fd),
              }),
            });

            e.currentTarget.reset();
            load();
          }}
          className="flex flex-col gap-2"
        >
          {config.fields
            .filter((f: any) => {
              if (config.pk.length === 1 && config.pk.includes(f.name)) {
                return false;
              }
              return true;
            })
            .map((f: any) => (
              <input
                key={f.name}
                name={f.name}
                type={f.type}
                placeholder={f.name}
                className="border p-2 rounded"
              />
            ))}

          <button className="bg-blue-600 text-white p-2 rounded">
            Add
          </button>
        </form>
      </div>

      {/* Filters */}
      <div>
        <h3 className="text-sm font-medium mb-2">Filters</h3>

        {config.fields.map((f: any) => (
          <input
            key={f.name}
            placeholder={`Filter ${f.name}`}
            className="border p-2 rounded w-full mb-2"
            onChange={(e) => {
              // (you can wire this later to backend filters)
              console.log(f.name, e.target.value);
            }}
          />
        ))}
      </div>

    </aside>

    {/* ================= RIGHT: MAIN ================= */}
    <main className="flex-1 p-6 overflow-auto">

      {/* Tabs */}
      <div className="flex gap-2 border-b mb-4">
        {Object.keys(tables).map((t) => (
          <button
            key={t}
            onClick={() => setSelected(t)}
            className={`px-4 py-2 ${
              selected === t
                ? "border-b-2 border-blue-600 font-bold"
                : "text-gray-500"
            }`}
          >
            {t}
          </button>
        ))}
      </div>

      {/* Loading */}
      {loading && (
        <p className="mb-2 text-gray-500">Loading...</p>
      )}

      {/* Table */}
      <table className="w-full bg-white rounded-xl shadow-md overflow-hidden">
        <thead className="bg-gray-200">
          <tr>
            {config.fields.map((f: any) => (
              <th key={f.name} className="p-3 text-left">
                {f.name}
              </th>
            ))}
            <th></th>
          </tr>
        </thead>

        <tbody>
          {data.map((row: any, i: number) => (
            <tr
              key={`${selected}-${config.pk
                .map((k: string) => row[k] ?? "x")
                .join("-")}-${i}`}
              className="border-t hover:bg-gray-50"
            >
              {config.fields.map((f: any) => (
                <td key={f.name} className="p-3">
                  {row[f.name]}
                </td>
              ))}

              <td>
                <button
                  onClick={async () => {
                    await fetch("/api/delete", {
                      method: "POST",
                      headers: { "Content-Type": "application/json" },
                      body: JSON.stringify({
                        table: selected,
                        pk: config.pk.reduce((acc: any, k: string) => {
                          acc[k] = row[k];
                          return acc;
                        }, {}),
                      }),
                    });

                    load();
                  }}
                  className="text-red-600"
                >
                  🗑️
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

    </main>
  </div>
);
}